	@Test
	void boundedKernelProbePreservesDeterministicAndQueryStableValues() throws Exception {
		AtomicInteger calls = new AtomicInteger();
		AtomicBoolean probed = new AtomicBoolean();
		try (AutoCloseable registration = register(identity(Function.Determinism.DETERMINISTIC, calls, probed));
				var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
					"SELECT * WHERE { VALUES ?left {2} BIND(<" + FUNCTION_URI + ">(?left) AS ?side) "
							+ "BIND(NOW() AS ?first) BIND(NOW() AS ?second) }",
					null).getTupleExpr();
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			var compiled = LmdbNativeAggregateCompiler.tryCompile(expression, new QueryEvaluationContext.Minimal(null),
					strategy, (NativeLmdbQuerySource) dataset);
			assertThat(compiled).isInstanceOf(NativeRowsStep.class);
			NativeRowsStep step = (NativeRowsStep) compiled;
			assertThat(SlotPlan.encounterOrderReplaySafe(step.arg)).isTrue();
			SyntheticValueSource source = (SyntheticValueSource) step.evaluationSource();
			try {
				RowState row = new RowState(source, step.layout, EmptyBindingSet.getInstance());
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, step.layout)).isTrue();
				NativeRowsStep.initializeQueryBase(source, row.base);
				try (var proposal = LmdbNativeKernelExecution.proposeRows(step.arg, row, expression, true);
						var scope = LmdbNativeProbeDeadline.enter(LmdbNativeProbeDeadline.trippableOnly())) {
					assertThat(proposal).isNotNull();
					var observation = new LmdbNativeCostObservation(proposal.adaptiveEstimate(-1D),
							LmdbNativeAdaptiveCostModel.forSource(source), LmdbNativeCostObservation.Role.PROBE);
					NativeUnorderedInput replay = new NativeProbeBufferHarness().drainBounded(
							NativeUnorderedInput.rows(row, proposal.open()), observation, 16);
					try (RowCursor rows = replay.materializedRows()) {
						assertThat(rows.next()).isTrue();
						assertThat(row.view.getValue("side"))
								.isEqualTo(repository.getValueFactory().createLiteral(BigInteger.TWO));
						assertThat(row.view.getValue("first")).isNotNull().isEqualTo(row.view.getValue("second"));
						assertThat(rows.next()).isFalse();
					}
					assertThat(probed.get()).as("the actual native callback must run inside the bounded probe")
							.isTrue();
					assertThat(calls.get()).isPositive();
				}
			} finally {
				source.executionContext().close();
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void repeatableWitnessesKeepBulkEligibilityAndDefaultAdaptiveSemantics(boolean negated) throws Exception {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			connection.add(vf.createIRI("urn:s2"), vf.createIRI("urn:p"), vf.createIRI("urn:o"));
			connection.add(vf.createIRI("urn:s2"), vf.createIRI("urn:dislikes"), vf.createIRI("urn:o"));
		}
		String where = " WHERE { ?a <urn:p> ?b FILTER " + (negated ? "NOT " : "")
				+ "EXISTS { ?a <urn:dislikes> ?d } }";
		String aggregate = "SELECT (COUNT(DISTINCT ?a) AS ?n)" + where;
		TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, aggregate, null).getTupleExpr();
		List<String> expected = evaluate(expression.clone(), false);
		assertThat(expected).containsExactly("{n=" + repository.getValueFactory().createLiteral(BigInteger.ONE) + "}");
		long islands = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		long hosted = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		for (int round = 0; round < QUERY_REPETITIONS; round++) {
			assertThat(evaluate(expression.clone(), true)).containsExactlyElementsOf(expected);
		}
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islands);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hosted);

		try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(
					new SailDatasetTripleTermSource(repository.getValueFactory(), dataset), null, null, 0L,
					new EvaluationStatistics(), false);
			for (String query : List.of(aggregate, "SELECT ?a ?b" + where)) {
				TupleExpr operator = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
				while (operator instanceof UnaryTupleOperator unary && !(operator instanceof Group)
						&& !(operator instanceof Filter)) {
					operator = unary.getArg();
				}
				var compiled = LmdbNativeAggregateCompiler.tryCompile(operator,
						new QueryEvaluationContext.Minimal(null), strategy, (NativeLmdbQuerySource) dataset);
				SlotPlan arg = compiled instanceof NativeGroupStep group ? group.arg
						: compiled instanceof NativeRowsStep rows ? rows.arg : null;
				assertThat(arg).isNotNull();
				assertThat(SlotPlan.encounterOrderReplaySafe(arg))
						.as("repeatable witnesses retain bulk rows and bounded-probe eligibility")
						.isTrue();
			}
		}
	}

	private void assertVolatileExecutions(TupleExpr expression, AtomicInteger calls, AtomicBoolean probed,
			int expectedCalls, int expectedRows) {
		assertVolatileExecutions(expression, calls, probed, expectedCalls, expectedRows, false);
	}

	private void assertVolatileExecutions(TupleExpr expression, AtomicInteger calls, AtomicBoolean probed,
			int expectedCalls, int expectedRows, boolean ordered) {
		List<String> expected = evaluate(expression.clone(), false);
		assertThat(expected).hasSize(expectedRows);
		assertThat(calls.get()).as("generic oracle's invocation count").isEqualTo(expectedCalls);
		long islands = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		long hosted = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		for (int round = 0; round < QUERY_REPETITIONS; round++) {
			int before = calls.get();
			List<String> actual = evaluate(expression.clone(), true);
			if (ordered) {
				assertThat(actual).containsExactlyElementsOf(expected);
			} else {
				assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
			}
			assertThat(calls.get() - before).as("VOLATILE invocations in query round %s; trial=%s", round, probed.get())
					.isEqualTo(expectedCalls);
			assertThat(probed.get()).as("VOLATILE operands must never run in a discardable trial").isFalse();
		}
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islands);
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hosted);
	}

	private Extension scalarComparisons(boolean inner, boolean union) {
		TupleExpr input = union ? new Union(values("left", 2), values("left", 4)) : values("left", 2);
		Extension extension = new Extension(input);
		extension.addElement(
				new ExtensionElem(new CompareAny(scalarLeft(inner), scalarValues(inner, 1, 3), CompareOp.GT), "any"));
		extension.addElement(
				new ExtensionElem(new CompareAll(scalarLeft(inner), scalarValues(inner, 1, 3), CompareOp.LT), "all"));
		extension.addElement(new ExtensionElem(new In(scalarLeft(inner), scalarValues(inner, 1, 2)), "in"));
		return extension;
	}

	private ValueExpr scalarLeft(boolean inner) {
		return inner ? new Var("left") : new FunctionCall(FUNCTION_URI, new Var("left"));
	}

	private TupleExpr scalarValues(boolean inner, int... numbers) {
		if (!inner) {
			return values("right", numbers);
		}
		Extension extension = new Extension(values("input", numbers));
		extension.addElement(new ExtensionElem(new FunctionCall(FUNCTION_URI, new Var("input")), "right"));
		return new Projection(extension, new ProjectionElemList(new ProjectionElem("right")), false);
	}

	private BindingSetAssignment values(String name, int... numbers) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(new LinkedHashSet<>(Set.of(name)));
		List<BindingSet> bindings = new ArrayList<>();
		for (int number : numbers) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding(name, repository.getValueFactory().createLiteral(number));
			bindings.add(row);
		}
		assignment.setBindingSets(bindings);
		return assignment;
	}

	private static Function identity(Function.Determinism determinism, AtomicInteger calls, AtomicBoolean probed) {
		return new Function() {
			@Override
			public String getURI() {
				return FUNCTION_URI;
			}

			@Override
			public Determinism getDeterminism() {
				return determinism;
			}

			@Override
			public Value evaluate(ValueFactory valueFactory, Value... args) {
				calls.incrementAndGet();
				if (probed != null && LmdbNativeProbeDeadline.currentOrNull() != null) {
					probed.set(true);
				}
				return args[0];
			}
		};
	}

	private static AutoCloseable register(Function function) {
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previous = registry.get(function.getURI()).orElse(null);
		registry.add(function);
		return () -> {
			registry.remove(function);
			if (previous != null) {
				registry.add(previous);
			}
		};
	}

	private List<String> evaluate(TupleExpr expression, boolean nativeEnabled) {
		return evaluate(expression, nativeEnabled, Integer.MAX_VALUE);
	}

	private List<String> evaluate(TupleExpr expression, boolean nativeEnabled, int maxRows) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (NotifyingSailConnection connection = store.getConnection();
				CloseableIteration<? extends BindingSet> rows = connection.evaluate(expression, null,
						EmptyBindingSet.getInstance(), true)) {
			List<String> result = new ArrayList<>();
			while (result.size() < maxRows && rows.hasNext()) {
				TreeMap<String, String> bindings = new TreeMap<>();
				for (Binding binding : rows.next()) {
					bindings.put(binding.getName(), binding.getValue().toString());
				}
				result.add(bindings.toString());
			}
			return result;
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}
